package com.storybook.security;
import org.springframework.context.annotation.*; import org.springframework.http.HttpMethod; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.cors.*; import java.util.List;
@Configuration public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain filter(HttpSecurity h,JwtFilter jwt)throws Exception {h.csrf(c->c.disable()).cors(c->c.configurationSource(r->{var x=new CorsConfiguration();x.setAllowedOrigins(List.of("http://localhost:5173","http://127.0.0.1:5173","http://localhost:5174","http://127.0.0.1:5174"));x.setAllowedMethods(List.of("GET","POST","PUT","DELETE","PATCH","OPTIONS"));x.setAllowedHeaders(List.of("*"));x.setAllowCredentials(true);return x;})).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/v1/auth/**","/files/**","/swagger-ui/**","/v3/api-docs/**","/actuator/health").permitAll().requestMatchers(HttpMethod.GET,"/api/v1/community/**","/api/v1/presets/**").permitAll().requestMatchers("/api/admin/**").hasRole("ADMIN").requestMatchers("/api/v1/**").authenticated().anyRequest().permitAll()).addFilterBefore(jwt, UsernamePasswordAuthenticationFilter.class);return h.build();}}
